import React, { useState, useEffect } from 'react';
import { 
  Users, 
  UserPlus, 
  UserCheck, 
  UserX, 
  Calendar, 
  Clock, 
  DollarSign, 
  Activity,
  Target,
  CheckCircle,
  AlertTriangle,
  Plus,
  Download,
  BarChart3
} from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../../components/ui/card';
import { Button } from '../../components/ui/button';
import { Badge } from '../../components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../../components/ui/tabs';
import { LineChartComponent, BarChartComponent } from '../../components/ui/charts';

const HRDashboard = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [loading, setLoading] = useState(false);
  const [stats] = useState({
    totalEmployees: 24,
    activeEmployees: 22,
    newHires: 3,
    pendingLeaves: 5,
    totalSalary: 125000,
    averageSalary: 5208
  });

  const tabs = [
    { id: 'overview', label: 'Overview', icon: BarChart3 },
    { id: 'employees', label: 'Employees', icon: Users },
    { id: 'attendance', label: 'Attendance', icon: Calendar },
    { id: 'leaves', label: 'Leaves', icon: Clock },
    { id: 'payroll', label: 'Payroll', icon: DollarSign },
  ];

  // Sample data for charts
  const attendanceData = [
    { name: 'Mon', present: 22, absent: 2 },
    { name: 'Tue', present: 23, absent: 1 },
    { name: 'Wed', present: 21, absent: 3 },
    { name: 'Thu', present: 24, absent: 0 },
    { name: 'Fri', present: 22, absent: 2 },
  ];

  const salaryData = [
    { name: 'Jan', salary: 120000 },
    { name: 'Feb', salary: 122000 },
    { name: 'Mar', salary: 123000 },
    { name: 'Apr', salary: 124000 },
    { name: 'May', salary: 125000 },
    { name: 'Jun', salary: 125000 },
  ];

  const departmentData = [
    { name: 'Engineering', value: 12 },
    { name: 'Design', value: 5 },
    { name: 'Marketing', value: 4 },
    { name: 'Sales', value: 3 },
  ];

  useEffect(() => {
    loadHRData();
  }, []);

  const loadHRData = async () => {
    setLoading(true);
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      setLoading(false);
    } catch (error) {
      console.error('Error loading HR data:', error);
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(amount);
  };

  const getStatusColor = (status) => {
    const colors = {
      active: 'bg-green-100 text-green-800',
      inactive: 'bg-red-100 text-red-800',
      pending: 'bg-yellow-100 text-yellow-800',
      approved: 'bg-blue-100 text-blue-800'
    };
    return colors[status] || colors.pending;
  };

  const renderOverviewTab = () => {
    const overviewCards = [
      {
        name: 'Total Employees',
        value: stats.totalEmployees,
        change: '+2',
        changeType: 'positive',
        icon: Users,
        color: 'text-blue-600'
      },
      {
        name: 'Active Employees',
        value: stats.activeEmployees,
        change: '+1',
        changeType: 'positive',
        icon: UserCheck,
        color: 'text-green-600'
      },
      {
        name: 'New Hires',
        value: stats.newHires,
        change: 'This month',
        changeType: 'neutral',
        icon: UserPlus,
        color: 'text-purple-600'
      },
      {
        name: 'Pending Leaves',
        value: stats.pendingLeaves,
        change: 'Requests',
        changeType: 'neutral',
        icon: Calendar,
        color: 'text-orange-600'
      }
    ];

    return (
      <div className="space-y-6">
        {/* Stats Cards */}
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
          {overviewCards.map((card, index) => {
            const Icon = card.icon;
            return (
              <Card key={index}>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">
                    {card.name}
                  </CardTitle>
                  <Icon className={`h-4 w-4 ${card.color}`} />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">{card.value}</div>
                  <p className="text-xs text-muted-foreground">
                    <span className={card.changeType === 'positive' ? 'text-green-600' : 'text-muted-foreground'}>
                      {card.change}
                    </span> from last month
                  </p>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {/* Charts Section */}
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-7">
          <div className="col-span-4">
            <Card>
              <CardHeader>
                <CardTitle>Employee Growth</CardTitle>
                <CardDescription>
                  Employee count over the last 6 months
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="h-[200px] flex items-center justify-center bg-muted/20 rounded-lg">
                  <div className="text-center">
                    <BarChart3 className="h-12 w-12 text-muted-foreground mx-auto mb-2" />
                    <p className="text-sm text-muted-foreground">Employee growth chart will be displayed here</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          <Card className="col-span-3">
            <CardHeader>
              <CardTitle>Department Distribution</CardTitle>
              <CardDescription>
                Employees by department
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {departmentData.map((dept, index) => (
                  <div key={index} className="flex items-center justify-between">
                    <div className="space-y-1">
                      <p className="text-sm font-medium leading-none">
                        {dept.name}
                      </p>
                      <p className="text-sm text-muted-foreground">
                        {dept.value} employees
                      </p>
                    </div>
                    <div className="text-right">
                      <p className="text-sm font-medium">
                        {((dept.value / stats.totalEmployees) * 100).toFixed(1)}%
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Quick Actions */}
        <Card>
          <CardHeader>
            <CardTitle>Quick Actions</CardTitle>
            <CardDescription>
              Common HR operations
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
              <Button variant="outline" className="flex items-center space-x-3 p-4 h-auto">
                <UserPlus className="w-4 h-4 text-blue-600" />
                <span className="text-sm font-medium">Add Employee</span>
              </Button>
              <Button variant="outline" className="flex items-center space-x-3 p-4 h-auto">
                <Calendar className="w-4 h-4 text-green-600" />
                <span className="text-sm font-medium">Manage Leaves</span>
              </Button>
              <Button variant="outline" className="flex items-center space-x-3 p-4 h-auto">
                <DollarSign className="w-4 h-4 text-purple-600" />
                <span className="text-sm font-medium">Process Payroll</span>
              </Button>
              <Button variant="outline" className="flex items-center space-x-3 p-4 h-auto">
                <Download className="w-4 h-4 text-orange-600" />
                <span className="text-sm font-medium">Export Report</span>
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  };

  const renderEmployeesTab = () => {
    const employees = [
      {
        id: 1,
        name: 'John Doe',
        email: 'john.doe@company.com',
        department: 'Engineering',
        position: 'Senior Developer',
        status: 'active',
        joinDate: '2023-01-15',
        salary: 85000
      },
      {
        id: 2,
        name: 'Sarah Wilson',
        email: 'sarah.wilson@company.com',
        department: 'Design',
        position: 'UI/UX Designer',
        status: 'active',
        joinDate: '2023-03-20',
        salary: 75000
      },
      {
        id: 3,
        name: 'Mike Johnson',
        email: 'mike.johnson@company.com',
        department: 'Marketing',
        position: 'Marketing Manager',
        status: 'active',
        joinDate: '2023-02-10',
        salary: 70000
      }
    ];

    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <div>
            <h3 className="text-lg font-medium">Employees</h3>
            <p className="text-sm text-muted-foreground">Manage your team members</p>
          </div>
          <Button>
            <Plus className="mr-2 h-4 w-4" />
            Add Employee
          </Button>
        </div>

        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {employees.map((employee) => (
            <Card key={employee.id}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-lg">{employee.name}</CardTitle>
                  <Badge className={getStatusColor(employee.status)}>
                    {employee.status}
                  </Badge>
                </div>
                <CardDescription>{employee.email}</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <div className="flex justify-between text-sm">
                    <span>Department</span>
                    <span className="font-medium">{employee.department}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span>Position</span>
                    <span className="font-medium">{employee.position}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span>Join Date</span>
                    <span>{new Date(employee.joinDate).toLocaleDateString()}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span>Salary</span>
                    <span className="font-medium">{formatCurrency(employee.salary)}</span>
                  </div>
                  <div className="flex space-x-2">
                    <Button variant="outline" size="sm" className="flex-1">
                      View
                    </Button>
                    <Button variant="outline" size="sm" className="flex-1">
                      Edit
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  };

  const renderAttendanceTab = () => {
    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <div>
            <h3 className="text-lg font-medium">Attendance Tracking</h3>
            <p className="text-sm text-muted-foreground">Monitor employee attendance</p>
          </div>
          <Button>
            <Download className="mr-2 h-4 w-4" />
            Export Report
          </Button>
        </div>

        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                Present Today
              </CardTitle>
              <UserCheck className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">22</div>
              <p className="text-xs text-muted-foreground">
                <span className="text-green-600">+2</span> from yesterday
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                Absent Today
              </CardTitle>
              <UserX className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">2</div>
              <p className="text-xs text-muted-foreground">
                <span className="text-red-600">-1</span> from yesterday
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                Late Arrivals
              </CardTitle>
              <Clock className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">3</div>
              <p className="text-xs text-muted-foreground">
                <span className="text-yellow-600">+1</span> from yesterday
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                Attendance Rate
              </CardTitle>
              <Activity className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">91.7%</div>
              <p className="text-xs text-muted-foreground">
                <span className="text-green-600">+2.1%</span> from last week
              </p>
            </CardContent>
          </Card>
        </div>

        <div className="col-span-4">
          <BarChartComponent data={attendanceData} />
        </div>
      </div>
    );
  };

  const renderLeavesTab = () => {
    const leaves = [
      {
        id: 1,
        employee: 'John Doe',
        type: 'Sick Leave',
        startDate: '2024-12-05',
        endDate: '2024-12-07',
        status: 'approved',
        days: 3
      },
      {
        id: 2,
        employee: 'Sarah Wilson',
        type: 'Annual Leave',
        startDate: '2024-12-15',
        endDate: '2024-12-20',
        status: 'pending',
        days: 5
      },
      {
        id: 3,
        employee: 'Mike Johnson',
        type: 'Personal Leave',
        startDate: '2024-12-10',
        endDate: '2024-12-10',
        status: 'approved',
        days: 1
      }
    ];

    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <div>
            <h3 className="text-lg font-medium">Leave Management</h3>
            <p className="text-sm text-muted-foreground">Manage employee leave requests</p>
          </div>
          <Button>
            <Plus className="mr-2 h-4 w-4" />
            Add Leave Request
          </Button>
        </div>

        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {leaves.map((leave) => (
            <Card key={leave.id}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-lg">{leave.employee}</CardTitle>
                  <Badge className={getStatusColor(leave.status)}>
                    {leave.status}
                  </Badge>
                </div>
                <CardDescription>{leave.type}</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <div className="flex justify-between text-sm">
                    <span>Start Date</span>
                    <span>{new Date(leave.startDate).toLocaleDateString()}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span>End Date</span>
                    <span>{new Date(leave.endDate).toLocaleDateString()}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span>Days</span>
                    <span className="font-medium">{leave.days}</span>
                  </div>
                  <div className="flex space-x-2">
                    <Button variant="outline" size="sm" className="flex-1">
                      Approve
                    </Button>
                    <Button variant="outline" size="sm" className="flex-1">
                      Reject
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  };

  const renderPayrollTab = () => {
    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <div>
            <h3 className="text-lg font-medium">Payroll Management</h3>
            <p className="text-sm text-muted-foreground">Manage employee salaries and payroll</p>
          </div>
          <Button>
            <Download className="mr-2 h-4 w-4" />
            Process Payroll
          </Button>
        </div>

        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                Total Payroll
              </CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatCurrency(stats.totalSalary)}</div>
              <p className="text-xs text-muted-foreground">
                <span className="text-green-600">+5.2%</span> from last month
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                Average Salary
              </CardTitle>
              <Target className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatCurrency(stats.averageSalary)}</div>
              <p className="text-xs text-muted-foreground">
                <span className="text-green-600">+3.1%</span> from last month
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                Payroll Status
              </CardTitle>
              <CheckCircle className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">Processed</div>
              <p className="text-xs text-muted-foreground">
                <span className="text-green-600">On time</span> this month
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                Pending Payments
              </CardTitle>
              <AlertTriangle className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">0</div>
              <p className="text-xs text-muted-foreground">
                <span className="text-green-600">All clear</span> this month
              </p>
            </CardContent>
          </Card>
        </div>

        <div className="col-span-4">
          <LineChartComponent data={salaryData} />
        </div>
      </div>
    );
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'overview':
        return renderOverviewTab();
      case 'employees':
        return renderEmployeesTab();
      case 'attendance':
        return renderAttendanceTab();
      case 'leaves':
        return renderLeavesTab();
      case 'payroll':
        return renderPayrollTab();
      default:
        return renderOverviewTab();
    }
  };

  return (
    <div className="flex-1 space-y-8 p-8 pt-6">
      {/* Header */}
      <div className="flex items-center justify-between space-y-2">
        <h2 className="text-3xl font-bold tracking-tight">HR Management</h2>
        <div className="flex items-center space-x-2">
          <Button variant="outline" size="sm">
            <Download className="mr-2 h-4 w-4" />
            Export
          </Button>
          <Button size="sm">
            <Plus className="mr-2 h-4 w-4" />
            Add Employee
          </Button>
        </div>
      </div>

      {/* Description */}
      <div className="space-y-2">
        <p className="text-muted-foreground">
          Manage your team, track attendance, handle leaves, and process payroll.
        </p>
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-6">
        <TabsList className="grid w-full grid-cols-5">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            return (
              <TabsTrigger key={tab.id} value={tab.id} className="flex items-center space-x-2">
                <Icon className="w-4 h-4" />
                <span className="hidden sm:inline">{tab.label}</span>
              </TabsTrigger>
            );
          })}
        </TabsList>

        {/* Loading State */}
        {loading && (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
            <span className="ml-2 text-muted-foreground">Loading HR data...</span>
          </div>
        )}

        {/* Tab Content */}
        {!loading && (
          <TabsContent value={activeTab} className="space-y-6">
            {renderTabContent()}
          </TabsContent>
        )}
      </Tabs>
    </div>
  );
};

export default HRDashboard; 